package com.healpoint;

import org.springframework.dao.DataAccessException;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@RestController @RequestMapping("/api") @CrossOrigin(origins={"http://127.0.0.1:5500","http://localhost:5500","http://127.0.0.1:5501","http://localhost:5501"})
public class ApiController {
 private final JdbcTemplate db; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 public ApiController(JdbcTemplate db){this.db=db;}
 @GetMapping("/health") public Map<String,Object> health(){ db.queryForObject("SELECT 1",Integer.class); return Map.of("success",true,"service","HealPoint API","database","connected"); }
 @GetMapping("/departments") public List<Map<String,Object>> departments(){return db.queryForList("SELECT id, department_name AS name, is_active AS active FROM department ORDER BY department_name");}
 @GetMapping("/doctors") public List<Map<String,Object>> doctors(){return db.queryForList("SELECT d.id,d.doctor_name AS name,d.doctor_name,d.specialisation AS specialization,d.phone,d.is_active AS active,d.department_id,dp.department_name AS department FROM doctor d JOIN department dp ON dp.id=d.department_id ORDER BY d.doctor_name");}
 @GetMapping("/patients") public List<Map<String,Object>> patients(){return db.queryForList("SELECT id,patient_name AS name,patient_name,gender,date_of_birth AS dateOfBirth,phone,address,created_at AS createdAt FROM patient ORDER BY id DESC");}
 @GetMapping("/appointments") public List<Map<String,Object>> appointments(){return db.queryForList("SELECT a.id,a.patient_id AS patientId,p.patient_name AS patient,a.doctor_id AS doctorId,d.doctor_name AS doctor,a.appointment_date AS appointmentDate,a.slot_id AS slotId,t.slot_label AS slot,a.status FROM appointment a JOIN patient p ON p.id=a.patient_id JOIN doctor d ON d.id=a.doctor_id JOIN time_slot t ON t.id=a.slot_id ORDER BY a.appointment_date DESC,a.id DESC");}
 @GetMapping("/visits") public List<Map<String,Object>> visits(){return db.queryForList("SELECT v.id,v.appointment_id AS appointmentId,v.patient_id AS patientId,p.patient_name AS patient,v.doctor_id AS doctorId,d.doctor_name AS doctor,v.visit_date AS visitDate,v.notes FROM visit v JOIN patient p ON p.id=v.patient_id JOIN doctor d ON d.id=v.doctor_id ORDER BY v.visit_date DESC");}
 @GetMapping("/prescriptions") public List<Map<String,Object>> prescriptions(){return db.queryForList("SELECT pr.id,pr.visit_id AS visitId,pr.medicine_name AS medicine,pr.medicine_name,pr.dosage,pr.frequency,pr.duration,pr.instructions FROM prescription pr ORDER BY pr.id DESC");}
 @GetMapping("/bills") public List<Map<String,Object>> bills(){return db.queryForList("SELECT b.id,b.visit_id AS visitId,b.bill_date AS billDate,b.total_amount AS total,b.total_amount,b.payment_status AS status FROM bill b ORDER BY b.bill_date DESC");}
 @GetMapping("/audit-logs") public List<Map<String,Object>> audit(){return db.queryForList("SELECT id,entity_name AS entity,entity_id AS entityId,action_type AS action,changed_by AS changedBy,changed_at AS changedAt FROM audit_log ORDER BY changed_at DESC LIMIT 500");}
 @PostMapping("/doctors") public ResponseEntity<?> createDoctor(@RequestBody Map<String,Object> x){try{db.update("INSERT INTO doctor(department_id,doctor_name,specialisation,phone) VALUES(?,?,?,?)",num(x,"departmentId"),str(x,"name",str(x,"doctor_name","")),str(x,"specialization",str(x,"specialisation",null)),str(x,"phone",null));return created("Doctor created");}catch(Exception e){return bad(e);}}
 @PutMapping("/doctors/{id}") public ResponseEntity<?> updateDoctor(@PathVariable int id,@RequestBody Map<String,Object>x){try{db.update("UPDATE doctor SET doctor_name=COALESCE(?,doctor_name),specialisation=COALESCE(?,specialisation),phone=COALESCE(?,phone),department_id=COALESCE(?,department_id),is_active=COALESCE(?,is_active) WHERE id=?",str(x,"name",null),str(x,"specialization",null),str(x,"phone",null),nullableNum(x,"departmentId"),nullableBool(x,"active"),id);return ok("Doctor updated");}catch(Exception e){return bad(e);}}
 @DeleteMapping("/doctors/{id}") public ResponseEntity<?> deleteDoctor(@PathVariable int id){try{db.update("UPDATE doctor SET is_active=FALSE WHERE id=?",id);return ok("Doctor deactivated");}catch(Exception e){return bad(e);}}
 @PostMapping("/patients") public ResponseEntity<?> createPatient(@RequestBody Map<String,Object>x){try{db.update("INSERT INTO patient(patient_name,gender,date_of_birth,phone,address) VALUES(?,?,?,?,?)",str(x,"name",str(x,"patient_name","")),str(x,"gender","Other"),date(x,"dateOfBirth",x.get("date_of_birth")),str(x,"phone",null),str(x,"address",null));return created("Patient created");}catch(Exception e){return bad(e);}}
 @PutMapping("/patients/{id}") public ResponseEntity<?> updatePatient(@PathVariable int id,@RequestBody Map<String,Object>x){try{db.update("UPDATE patient SET patient_name=COALESCE(?,patient_name),phone=COALESCE(?,phone),address=COALESCE(?,address) WHERE id=?",str(x,"name",null),str(x,"phone",null),str(x,"address",null),id);return ok("Patient updated");}catch(Exception e){return bad(e);}}
 @DeleteMapping("/patients/{id}") public ResponseEntity<?> deletePatient(@PathVariable int id){return ResponseEntity.status(405).body(Map.of("success",false,"message","Patients are not hard-deleted; deactivate/archive workflow must be configured."));}
 @PostMapping("/appointments") public ResponseEntity<?> book(@RequestBody Map<String,Object>x){try{db.update("INSERT INTO appointment(patient_id,doctor_id,appointment_date,slot_id,status) VALUES(?,?,?,?, 'Scheduled')",num(x,"patientId"),num(x,"doctorId"),date(x,"appointmentDate",x.get("date")),num(x,"slotId"));return created("Appointment booked");}catch(Exception e){return bad(e);}}
 @PutMapping("/appointments/{id}/status") public ResponseEntity<?> status(@PathVariable int id,@RequestBody Map<String,Object>x){try{db.update("UPDATE appointment SET status=? WHERE id=?",str(x,"status","Scheduled"),id);return ok("Appointment status updated");}catch(Exception e){return bad(e);}}
 @PutMapping("/appointments/{id}/cancel") public ResponseEntity<?> cancel(@PathVariable int id){try{db.update("UPDATE appointment SET status='Cancelled' WHERE id=?",id);return ok("Appointment cancelled");}catch(Exception e){return bad(e);}}
 @PostMapping("/visits") public ResponseEntity<?> visit(@RequestBody Map<String,Object>x){try{db.update("INSERT INTO visit(appointment_id,patient_id,doctor_id,visit_date,notes,created_by_user_id) VALUES(?,?,?,?,?,?)",num(x,"appointmentId"),num(x,"patientId"),num(x,"doctorId"),date(x,"visitDate",null),str(x,"notes",null),num(x,"createdByUserId"));return created("Visit saved");}catch(Exception e){return bad(e);}}
 @PostMapping("/prescriptions") public ResponseEntity<?> prescription(@RequestBody Map<String,Object>x){try{db.update("INSERT INTO prescription(visit_id,medicine_name,dosage,frequency,duration,instructions,created_by_user_id) VALUES(?,?,?,?,?,?,?)",num(x,"visitId"),str(x,"medicine",str(x,"medicine_name","")),str(x,"dosage",""),str(x,"frequency",""),str(x,"duration",""),str(x,"instructions",null),num(x,"createdByUserId"));return created("Prescription saved");}catch(Exception e){return bad(e);}}
 @PostMapping("/bills") public ResponseEntity<?> bill(@RequestBody Map<String,Object>x){try{db.update("INSERT INTO bill(visit_id,bill_date,total_amount,payment_status) VALUES(?,?,?,?)",num(x,"visitId"),date(x,"billDate",null),x.getOrDefault("total",0),str(x,"status","Pending"));return created("Bill created");}catch(Exception e){return bad(e);}}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,Object>x){try{String email=str(x,"email",str(x,"username",""));String password=str(x,"password","");List<Map<String,Object>> rows=db.queryForList("SELECT u.id,u.username,u.full_name,u.email,u.password_hash,u.is_active,r.role_name FROM app_user u JOIN user_role ur ON ur.user_id=u.id JOIN role r ON r.id=ur.role_id WHERE u.email=? OR u.username=?",email,email);for(var u:rows){Object hash=u.get("password_hash");if(Boolean.TRUE.equals(u.get("is_active")) && hash!=null && encoder.matches(password,hash.toString())){String role=u.get("role_name").toString();String requested=str(x,"role",role);if(!role.equalsIgnoreCase(requested))continue;return ResponseEntity.ok(Map.of("success",true,"user",Map.of("id",u.get("id"),"name",u.get("full_name"),"email",u.getOrDefault("email",""),"role",role)));}}return ResponseEntity.status(401).body(Map.of("success",false,"message","Invalid credentials or role."));}catch(Exception e){return bad(e);}}
 @PostMapping("/auth/register") @Transactional public ResponseEntity<?> register(@RequestBody Map<String,Object>x){try{String name=str(x,"name","");String email=str(x,"email","").toLowerCase(Locale.ROOT);String password=str(x,"password","");if(name.isBlank()||email.isBlank()||password.length()<8)return ResponseEntity.badRequest().body(Map.of("success",false,"message","Name, email and password (minimum 8 characters) are required."));String phone=str(x,"phone",null);db.update("INSERT INTO app_user(username,full_name,email,phone,password_hash,password_algo,is_active) VALUES(?,?,?,?,?,'bcrypt',TRUE)",email,name,email,phone,encoder.encode(password));Integer uid=db.queryForObject("SELECT id FROM app_user WHERE username=?",Integer.class,email);db.update("INSERT INTO patient(patient_name,gender,date_of_birth,phone,address) VALUES(?,?,?,?,?)",name,str(x,"gender","Other"),date(x,"dateOfBirth",null),phone,str(x,"address",null));Integer rid=db.queryForObject("SELECT id FROM role WHERE UPPER(role_name)='PATIENT' LIMIT 1",Integer.class);db.update("INSERT INTO user_role(user_id,role_id) VALUES(?,?)",uid,rid);return created("Patient account created");}catch(Exception e){return bad(e);}}
 private int num(Map<String,Object>x,String k){Object v=x.get(k);if(v==null)throw new IllegalArgumentException("Missing required field: "+k);return Integer.parseInt(v.toString());}
 private Integer nullableNum(Map<String,Object>x,String k){return x.get(k)==null?null:Integer.valueOf(x.get(k).toString());}
 private Boolean nullableBool(Map<String,Object>x,String k){return x.get(k)==null?null:Boolean.valueOf(x.get(k).toString());}
 private String str(Map<String,Object>x,String k,String d){Object v=x.get(k);return v==null?d:v.toString();}
 private java.sql.Date date(Map<String,Object>x,String k,Object fallback){Object v=x.getOrDefault(k,fallback);if(v==null||v.toString().isBlank())return new java.sql.Date(System.currentTimeMillis());return java.sql.Date.valueOf(v.toString().substring(0,10));}
 private ResponseEntity<Map<String,Object>> created(String m){return ResponseEntity.status(201).body(Map.of("success",true,"message",m));}
 private ResponseEntity<Map<String,Object>> ok(String m){return ResponseEntity.ok(Map.of("success",true,"message",m));}
 private ResponseEntity<Map<String,Object>> bad(Exception e){String m=e.getMessage()==null?"Request failed":e.getMessage(); if(e instanceof DataAccessException)m="Database rejected the request. Check required fields, relationships, and whether the SQL migrations have been applied.";return ResponseEntity.status(400).body(Map.of("success",false,"message",m));}
}
